/**
 * @planks("I click the toggle-all checkbox")
 */
App.prototype.toggleAllTodos = function (checked) {
	for (var i = 0; i < this.todos.length; i++) {
		this.todos[i].completed = checked;
	}
	this.store.save(this.todos);

	// Surgical DOM update: toggle every visible li instead of full re-render.
	// For filtered views, items that no longer match the filter are removed.
	var lis = this.todoList.querySelectorAll('li');
	for (var j = 0; j < lis.length; j++) {
		var li = lis[j];
		var todo = this.todos.filter(function (t) { return t.id == li.dataset.id; })[0];
		if (!todo) continue;

		if ((this.filter === 'active' && todo.completed) ||
			(this.filter === 'completed' && !todo.completed)) {
			li.parentNode.removeChild(li);
			j--; // adjust index after removal
		} else {
			li.classList.toggle('completed', todo.completed);
			var checkbox = li.querySelector('.toggle');
			if (checkbox) checkbox.checked = todo.completed;
		}
	}

	this.updateUI();
};

